<?php $title='Systemstatus';$labels=['ok'=>'OK','warning'=>'Warnung','error'=>'Fehler']; ?>
<div class="page-header split"><div><p class="eyebrow">Administration · System</p><h1>Systemstatus</h1><p>Letzter Check: <?= e(format_datetime($result['checked_at'])) ?> · Gesamtstatus <?= e(strtoupper($result['overall'])) ?></p></div><form method="post" action="<?= e(url('admin/system/status/check')) ?>"><?= csrf_field() ?><button class="button primary" type="submit">Systemcheck jetzt ausführen</button></form></div>
