<?php if(can('system.maintenance.manage')):?><div class="panel"><h2>Wartungsmodus</h2><p>Normale Benutzer sehen die Wartungsseite und können nicht weiterarbeiten. Administratoren bleiben arbeitsfähig.</p><form method="post" action="<?= e(url('admin/system/maintenance')) ?>" class="inline-actions"><?= csrf_field() ?><input type="hidden" name="enabled" value="<?= $maintenance?0:1 ?>"><button class="button <?= $maintenance?'secondary':'danger' ?>" type="submit"><?= $maintenance?'Wartungsmodus beenden':'Wartungsmodus aktivieren' ?></button><span class="badge <?= $maintenance?'warning':'active' ?>"><?= $maintenance?'Aktiv':'Aus' ?></span></form></div><?php endif;?>
